+
+message BlockDeleteEventParams {
+    string block_key = 1;
+    string medium = 2; // cache tier/namespace, e.g. "mem", "disk", "gpu", "hbm"
+    // Required component names to remove from this block location.
+    repeated string spec_names = 3;
