+
+message BlockSnapshotItem {
+    string block_key = 1;
+    string medium = 2; // cache tier/namespace, e.g. "mem", "disk", "gpu", "hbm"
+    repeated LocationSpec specs = 3;
+}
+
+message BlockSnapshotEventParams {
+    // Legacy single-medium form. New callers should set medium on every block.
