+            "http://w0:30000",
+            vec![clear(), report(3)],
+            None,
+        );
+        let translated = translate_batch(
+            &request,
+            false,
+            &[TierType::TierHbm],
+            &["hbm".into()],
+            "event_report://worker-0",
+        );
+        let shape: Vec<&str> = translated
+            .segments
+            .iter()
+            .map(|segment| match segment {
+                TranslatedSegment::Delta(_) => "delta",
+                TranslatedSegment::Clear { .. } => "clear",
+            })
+            .collect();
+        assert_eq!(shape, ["clear", "delta"]);
