+            Some(("w0".into(), "http://w0".into(), 3))
+        );
+        // A Tair KVCache over-report cannot exceed the query length.
+        assert_eq!(
+            prefix_entry(host("w0", 99), 10, &record("http://w0", true)).map(|e| e.2),
+            Some(10)
