+        );
+        assert_eq!(
+            prefix_entry(host("w0", -1), 10, &record("http://w0", true)),
+            None
+        );
+        assert_eq!(prefix_entry(host("w0", 5), 10, &record("", true)), None);
+        assert_eq!(
+            prefix_entry(host("w0", 5), 10, &record("http://w0", false)),
+            None
+        );
+    }
