+// SPDX-FileCopyrightText: Copyright (c) 2026 The SGLang Authors
+// SPDX-License-Identifier: Apache-2.0
+//
+// Vendored verbatim from Alibaba Cloud Tair KVCache Manager
+// (kv_cache_manager/protocol/protobuf/meta_service.proto, Apache-2.0) so the
+// KV Indexer's KVCM backend speaks the exact wire contract of a deployed
+// KVCM MetaService. Only three RPCs are used by this crate today
+// (RegisterInstance, ReportEvent, GetHostCacheState); the rest of the service
+// is kept so re-vendoring on KVCM upgrades stays a mechanical file copy with
+// no hand-edited subset to drift. Do not edit the definitions below.
+
+syntax = "proto3";
+
+package kv_cache_manager.proto.meta;
+
+option cc_generic_services = false;
+// HTTP handlers keep request/response messages on one request-scoped arena.
+// This is a C++ allocation policy only; it does not change the wire or JSON
+// representation of any MetaService message.
+option cc_enable_arenas = true;
+
+enum ErrorCode {
+    UNSPECIFIED = 0;
+    OK = 1;
+    UNSUPPORTED = 2;
+    INTERNAL_ERROR = 3;
+    SERVICE_NOT_READY = 4;
+    INVALID_ARGUMENT = 5;
+    DUPLICATE_ENTITY = 6; // 注册时如果发现模型信息不同，返回这个
+    REACH_MAX_ENTITY_CAPACITY = 7;
+    INSTANCE_NOT_EXIST = 8;
+    SERVER_NOT_LEADER = 9; // 高可用部署模式下，请求的接口只能在leader执行但请求的节点不是leader
+    NODE_NOT_REGISTERED = 10;
+    SNAPSHOT_IN_PROGRESS = 11;
+    reserved 12; // DELTA_IN_PROGRESS was removed: admitted deltas wait behind the snapshot gate.
+    SNAPSHOT_RATE_LIMITED = 13;
+    SNAPSHOT_REQUIRED = 14;
+
+    IO_ERROR = 20;
+    UNKNOWN_ERROR = 100;
+    ERROR_MAX = 65535;
+}
+
+message Status {
+    ErrorCode code = 1;
+    string message = 2;
+}
+
+message CommonResponseHeader {
+    Status status = 1;
+    string request_id = 2;
+    string tracer_result = 3;
+}
+
+message CommonResponse { CommonResponseHeader header = 1; }
+
+enum StorageType {
+    ST_UNSPECIFIED = 0;
+    ST_3FS = 1;
+    ST_MOONCAKE = 2;
+    ST_TAIRMEMPOOL = 3;
+    ST_NFS = 4;
+    ST_VCNS_3FS = 5;
+    ST_DUMMY = 6;
+    ST_EVENT_REPORT_L1P5 = 7;
+    ST_EVENT_REPORT_L2 = 8;
+    ST_TAIRMEMPOOL_SSD = 9;
+}
+
+// ---- Cache event reporting ----
+//
+// ReportEvent is the ingestion API used by cache subscribers. A subscriber
+// normalizes engine-specific cache signals (for example RTP-LLM full cache
+// snapshots or vLLM KV events) into block-level mutations on one storage
+// system. `storage_type` names that large storage/cache system; `medium` is
+// a block-level cache-tier attribute. LocationSpec describes every cache
+// component of the block, including
+// full-attention and mamba-state specs.
+
+enum ReportEventType {
+    EVENT_UNSPECIFIED = 0;
+    // Optional startup signal. A fresh reporter, including one observed after
+    // KVCM restart, may also be lazily initialized by its first valid
+    // HEARTBEAT/ADD/DELETE/SNAPSHOT. REGISTER is required to clear a
+    // same-process HOST_DOWN or liveness-cleanup tombstone.
+    EVENT_NODE_REGISTER = 1;
+    EVENT_BLOCK_ADD = 2;     // Reporter stored a block in one location
+    EVENT_BLOCK_DELETE = 3;  // Reporter removed a block from one location
+    EVENT_HOST_DOWN = 4;     // Reporter node is going down (graceful or detected)
+    EVENT_HEARTBEAT = 5;     // Reporter periodic heartbeat
+    EVENT_BLOCK_SNAPSHOT = 6; // Reporter sends one complete all-medium host snapshot
+}
+
+message NodeRegisterEventParams {
+    repeated string mediums = 1; // mediums supported by the node, e.g. ["mem","disk"]
+}
+
+message BlockAddEventParams {
+    // Signed int64 decimal, or unsigned uint64 decimal mapped to the same
+    // internal 64-bit key (e.g. UINT64_MAX is equivalent to -1).
+    string block_key = 1;
+    string uri = 2;       // deprecated, use specs instead
+    string medium = 3;    // cache tier/namespace, e.g. "mem", "disk", "gpu", "hbm"
+    repeated LocationSpec specs = 4;
+}
+
+message BlockDeleteEventParams {
+    string block_key = 1;
+    string medium = 2; // cache tier/namespace, e.g. "mem", "disk", "gpu", "hbm"
+    // Required component names to remove from this block location.
+    repeated string spec_names = 3;
+}
+
+message BlockSnapshotItem {
+    string block_key = 1;
+    string medium = 2; // cache tier/namespace, e.g. "mem", "disk", "gpu", "hbm"
+    repeated LocationSpec specs = 3;
+}
+
+message BlockSnapshotEventParams {
+    // Legacy single-medium form. New callers should set medium on every block.
+    string medium = 1 [deprecated = true];
+    // Complete block set for (instance_id, reporter host_ip_port), across every
+    // medium owned by the reporter. Empty means the host owns no blocks.
+    // Do not paginate.
+    repeated BlockSnapshotItem blocks = 2;
+}
+
+message HostDownEventParams {
+}
+
+message HeartbeatEventParams {
+    // KVCM only refreshes last_heartbeat; system_status is opaque observability data
+    map<string, string> system_status = 1;
+}
+
+message EventItem {
+    ReportEventType event_type = 1;
+    oneof event_params {
+        NodeRegisterEventParams node_register = 2;
+        BlockAddEventParams block_add = 3;
+        BlockDeleteEventParams block_delete = 4;
+        HostDownEventParams host_down = 5;
+        HeartbeatEventParams heartbeat = 6;
+        BlockSnapshotEventParams block_snapshot = 7;
+    }
+}
+
+message ReportEventRequest {
+    string trace_id = 1;
+    string instance_id = 2;
+    string host_ip_port = 3;
+    repeated EventItem events = 4;
+    StorageType storage_type = 5; // required: declares the reporter's storage/event_report
+}
+
+message ReportEventResponse {
+    CommonResponseHeader header = 1;
+    // Non-empty only when partial failures happen.
+    repeated ErrorCode item_results = 2;
+    // Current process-local reconciliation generation for
+    // (instance_id, storage_type, reporter host_ip_port). The first
+    // ADD/DELETE may create it. After a successful full snapshot it is also
+    // the strict query-visibility generation; restart or snapshot failure
+    // temporarily falls back to soft visibility until a later snapshot.
+    string committed_snapshot_version = 3;
+    uint64 retry_after_ms = 4;
+    // Advisory: true while this process has no generation yet, and once on
+    // the ADD/DELETE request that lazily creates the first generation. The
+    // caller should schedule a full snapshot for reconciliation; realtime
+    // mutations remain accepted while that snapshot is pending.
+    bool snapshot_required = 5;
+    string extra_info = 6; // opaque JSON passed through from InstanceGroup
+}
+
+// 使用URI统一多种存储表示，由client或者connector负责解析
+// ThreeFSLocation: 3fs://na61_3fs_cluster_01/data_root/dir1/filename?offset=0&size=1024
+// MoonCakeLocation: mooncake://na61_mc_bucket_01/my_key1
+// TairMemPoolLocation: pace://na61_pace_cluster_?offset=0&size=200&node_id=worker.33&media_type=1
+// NfsLocation: file://nfs_01/data/dir1/filename?offset=1&size=1024
+message LocationSpec {
+    string name = 1; // 对应LocationSpecInfo中的name
+    string uri = 2;
+}
+
+message CacheLocation {
+    StorageType type = 1;
+    int32 spec_size = 2;
+    repeated LocationSpec location_specs = 3;
+}
+
+message LocationSpecInfo {
+    string name = 1; // 由外部确定，用于描述单个block内的多个分块。举例比如2TP部署，可以是有TP0、TP1。
+    int64 size = 2;
+}
+
+message ModelDeployment {
+    string model_name = 1;
+    string dtype = 2;             // torch的数据类型，比如FP8、BP8，TODO 对齐torch
+    bool use_mla = 3;             // latent attention，开启了之后只需要存两个矩阵
+    int32 tp_size = 4;            // 分多少tp，分partition
+    int32 dp_size = 5;            // 数据并行
